From a967224d345eb87e4f057b6f22e54b66b1099d56 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:14:24 +0100
Subject: [PATCH] containments/desktop: add a Copy Location action to the item
 menu

Desktop and Folder View items had no way to copy their path, unlike the
same items in Dolphin. Add Dolphin's Copy Location action after Copy,
with its Ctrl+Alt+C shortcut, copying the paths of the selected items.

BUG: 450688
---
 .../package/contents/ui/FolderView.qml        |  2 ++
 .../desktop/plugins/folder/foldermodel.cpp    | 24 +++++++++++++++++++
 .../desktop/plugins/folder/foldermodel.h      |  1 +
 3 files changed, 27 insertions(+)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..f2589ed361 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -1036,6 +1036,8 @@ FocusScope {
                         updateSelection(event.modifiers);
                     } else if (event.matches(StandardKey.Copy)) {
                         dir.copy();
+                    } else if (event.key === Qt.Key_C && event.modifiers === (Qt.ControlModifier | Qt.AltModifier)) {
+                        dir.copyLocation();
                     } else if (event.matches(StandardKey.Paste)) {
                         dir.paste();
                     } else if (event.matches(StandardKey.Cut)) {
diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..41ab452ae3 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -1830,6 +1830,10 @@ void FolderModel::createActions()
     QAction *cut = KStandardAction::cut(this, &FolderModel::cut, this);
     QAction *copy = KStandardAction::copy(this, &FolderModel::copy, this);

+    QAction *copyLocation = new QAction(QIcon::fromTheme(QStringLiteral("edit-copy-path")), i18nc("@action:inmenu", "Copy Location"), this);
+    copyLocation->setShortcut(QKeySequence(Qt::CTRL | Qt::ALT | Qt::Key_C));
+    connect(copyLocation, &QAction::triggered, this, &FolderModel::copyLocation);
+
     QAction *undo = KStandardAction::undo(manager, &KIO::FileUndoManager::undo, this);
     undo->setEnabled(manager->isUndoAvailable());
     undo->setShortcutContext(Qt::WidgetShortcut);
@@ -1868,6 +1872,7 @@ void FolderModel::createActions()
     m_actionCollection.addAction(QStringLiteral("cut"), cut);
     m_actionCollection.addAction(QStringLiteral("undo"), undo);
     m_actionCollection.addAction(QStringLiteral("copy"), copy);
+    m_actionCollection.addAction(QStringLiteral("copyLocation"), copyLocation);
     m_actionCollection.addAction(QStringLiteral("paste"), paste);
     m_actionCollection.addAction(QStringLiteral("pasteto"), pasteTo);
     m_actionCollection.addAction(QStringLiteral("refresh"), refresh);
@@ -2098,6 +2103,7 @@ void FolderModel::openContextMenu(QQuickItem *visualParent, Qt::KeyboardModifier
         if (!isTrashLink) {
             menu->addAction(m_actionCollection.action(QStringLiteral("cut")));
             menu->addAction(m_actionCollection.action(QStringLiteral("copy")));
+            menu->addAction(m_actionCollection.action(QStringLiteral("copyLocation")));
         }

         if (urls.length() == 1) {
@@ -2243,6 +2249,24 @@ void FolderModel::copy()
     QApplication::clipboard()->setMimeData(mimeData);
 }

+void FolderModel::copyLocation()
+{
+    QStringList locations;
+    const QModelIndexList indexes = m_selectionModel->selectedIndexes();
+    for (const QModelIndex &index : indexes) {
+        const KFileItem item = itemForIndex(index);
+        if (item.isNull()) {
+            continue;
+        }
+        const QString path = item.localPath();
+        locations.append(path.isEmpty() ? item.url().toDisplayString() : QDir::toNativeSeparators(path));
+    }
+
+    if (!locations.isEmpty()) {
+        QApplication::clipboard()->setText(locations.join(QLatin1Char('\n')));
+    }
+}
+
 void FolderModel::cut()
 {
     if (!m_selectionModel->hasSelection()) {
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..f85fdcde7a 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -273,6 +273,7 @@ public:

     Q_INVOKABLE void paste();
     Q_INVOKABLE void copy();
+    Q_INVOKABLE void copyLocation();
     Q_INVOKABLE void cut();
     Q_INVOKABLE void deleteSelected();
     Q_INVOKABLE void undo();
